import * as THREE from "three";
import { marianaPitReach } from "./mariana_pit_profile.js";

/** 连续环形沉积台地：椭圆喉道、起伏岩顶及同一网格导出的保守实体。 */
export function createMarianaLayer(parent, keep, { gate, material, bounds }) {
  const points = [],
    indices = [],
    colors = [],
    colliders = [];
  const segments = 96,
    rings = 9,
    thickness = 32;
  const rx = gate.width * 0.5,
    rz = gate.depthSize * 0.5;
  const pale = new THREE.Color(gate.color),
    dark = new THREE.Color(0x414653);
  const color = new THREE.Color();
  for (let layer = 0; layer < 2; layer++)
    for (let ring = 0; ring <= rings; ring++)
      for (let i = 0; i <= segments; i++) {
        const a = (i / segments) * Math.PI * 2,
          c = Math.cos(a),
          s = Math.sin(a);
        const inner =
          1 + Math.sin(a * 3 + gate.depth) * 0.12 + Math.cos(a * 7) * 0.07;
        const innerX = rx * c * inner,
          innerZ = rz * s * inner;
        const reach = marianaPitReach(gate.x, gate.z, a, -gate.depth) + 24;
        const t = ring / rings;
        const x = gate.x + THREE.MathUtils.lerp(innerX, c * (reach + 10), t);
        const z = gate.z + THREE.MathUtils.lerp(innerZ, s * (reach + 10), t);
        const relief =
          t *
          (Math.sin(x * 0.047 + z * 0.025) * 9 +
            Math.sin(z * 0.084 - x * 0.023) * 4);
        const y = -gate.depth + relief - layer * thickness;
        points.push(x, y, z);
        color
          .copy(dark)
          .lerp(
            pale,
            0.12 + (0.5 + 0.5 * Math.sin(z * 0.063 + x * 0.036)) * 0.25,
          );
        if (layer) color.multiplyScalar(0.75);
        color.toArray(colors, colors.length);
      }
  const row = segments + 1,
    stride = (rings + 1) * row;
  for (let j = 0; j < rings; j++)
    for (let i = 0; i < segments; i++) {
      const a = j * row + i,
        b = a + row;
      indices.push(a, a + 1, b, b, a + 1, b + 1);
      indices.push(
        a + stride,
        b + stride,
        a + 1 + stride,
        b + stride,
        b + 1 + stride,
        a + 1 + stride,
      );
      // 单元包络保守覆盖岩面，不把整个房间或下降口变为避障球。
      const ids = [a, a + 1, b, b + 1],
        lo = [Infinity, Infinity, Infinity],
        hi = [-Infinity, -Infinity, -Infinity];
      for (const id of ids)
        for (let k = 0; k < 3; k++) {
          lo[k] = Math.min(lo[k], points[id * 3 + k]);
          hi[k] = Math.max(hi[k], points[id * 3 + k]);
        }
      lo[1] -= thickness;
      colliders.push({
        type: "box",
        id: `layer_${gate.id}_${j}_${i}`,
        x: (lo[0] + hi[0]) / 2,
        y: (lo[1] + hi[1]) / 2,
        z: (lo[2] + hi[2]) / 2,
        halfSize: new THREE.Vector3(
          (hi[0] - lo[0]) / 2,
          (hi[1] - lo[1]) / 2,
          (hi[2] - lo[2]) / 2,
        ),
      });
    }
  for (const ring of [0, rings])
    for (let i = 0; i < segments; i++) {
      const a = ring * row + i,
        b = a + 1;
      indices.push(a, b, a + stride, b, b + stride, a + stride);
    }
  const geometry = keep(new THREE.BufferGeometry());
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(points, 3),
  );
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = `trench_layer_${gate.id}`;
  parent.add(mesh);
  return colliders;
}

/** 波纹只留在自然椭圆入口，边缘渐隐，不绘制矩形平台或强烈同心靶标。 */
export function createMarianaSeal(parent, keep, gate, time) {
  const mat = keep(
    new THREE.MeshBasicMaterial({
      color: gate.color,
      transparent: true,
      opacity: 0.24,
      side: THREE.DoubleSide,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    }),
  );
  mat.onBeforeCompile = (s) => {
    s.uniforms.pressureTime = time;
    s.vertexShader = s.vertexShader
      .replace("#include <common>", "#include <common>\nvarying vec2 sealUv;")
      .replace(
        "#include <begin_vertex>",
        "#include <begin_vertex>\nsealUv=uv;",
      );
    s.fragmentShader = s.fragmentShader
      .replace(
        "#include <common>",
        "#include <common>\nvarying vec2 sealUv;uniform float pressureTime;",
      )
      .replace(
        "#include <color_fragment>",
        `#include <color_fragment>
      vec2 q=(sealUv-.5)*2.;float r=length(q);
      float veil=.5+.5*sin(q.x*13.+sin(q.y*9.-pressureTime*.35)*2.+pressureTime*.5);
      float edge=smoothstep(.62,.91,r)*(1.-smoothstep(.91,1.,r));
      diffuseColor.a*=((.13+veil*.12)*(1.-smoothstep(.75,1.,r))+edge*.7);`,
      );
  };
  mat.customProgramCacheKey = () => "mariana_organic_seal_v2";
  const curtain = keep(new THREE.CircleGeometry(1, 96));
  const vertices = curtain.attributes.position;
  for (let i = 1; i < vertices.count; i++) {
    const x = vertices.getX(i),
      y = vertices.getY(i),
      a = Math.atan2(y, x);
    const shape =
      1 + Math.sin(a * 3 + gate.depth) * 0.12 + Math.cos(a * 7) * 0.07;
    vertices.setXY(i, x * shape, y * shape);
  }
  curtain.computeBoundingSphere();
  const membrane = new THREE.Mesh(curtain, mat);
  membrane.rotation.x = -Math.PI / 2;
  membrane.scale.set(gate.width * 0.5, gate.depthSize * 0.5, 1);
  membrane.position.set(gate.x, -gate.depth, gate.z);
  membrane.name = `pressure_seal_${gate.id}`;
  parent.add(membrane);
  const barrier = {
    type: "ellipsoid",
    id: `seal_${gate.id}`,
    x: gate.x,
    y: -gate.depth - 1,
    z: gate.z,
    axes: new THREE.Vector3(gate.width * 0.61, 3, gate.depthSize * 0.61),
  };
  return { gate, membrane, barrier };
}

mariana_pit_profile.js.source:
export const MARIANA_PIT_SEGMENTS = 144;

/** 纵深中轴和非对称半径随深度偏移；轮廓不是矩形裁切，也不是固定圆柱。 */
export function marianaPitFrame(y) {
  return {
    x: Math.sin(y * 0.0031) * 9 + Math.sin(y * 0.008) * 4,
    z: -412 + Math.sin(y * 0.0025) * 10,
    rx: 235 + Math.sin(y * 0.003) * 10 + Math.cos(y * 0.011) * 8,
    front:
      200 +
      145 * Math.exp(-Math.pow(y / 360, 2)) +
      Math.sin(y * 0.004) * 10 +
      Math.cos(y * 0.009) * 8,
    back: 275 + Math.sin(y * 0.0035) * 12 + Math.cos(y * 0.007) * 8,
  };
}

export function marianaPitPoint(angle, y) {
  const f = marianaPitFrame(y),
    c = Math.cos(angle),
    s = Math.sin(angle),
    lobe =
      1 +
      Math.sin(angle * 3 + y * 0.002) * 0.055 +
      Math.cos(angle * 5 - y * 0.003 + 1.2) * 0.035 +
      Math.sin(angle * 9 + y * 0.012) * 0.018;
  return [f.x + c * f.rx * lobe, f.z + s * (s >= 0 ? f.front : f.back) * lobe];
}

/** 雷达只描绘当前水层的坑壁截面，不把保护性矩形边界误画成海沟形状。 */
export function marianaPitContour(y) {
  return Array.from({ length: 72 }, (_, i) =>
    marianaPitPoint((i * Math.PI * 2) / 72, y),
  );
}

/** 浅滩入口的唇缘向下敞开，允许出生水层沿斜坡进入坑内。 */
export function marianaPitRim(angle) {
  return (
    -42 -
    Math.pow(Math.max(0, Math.sin(angle)), 4) * 122 +
    Math.sin(angle * 5) * 7
  );
}

/** 从关卡中心射向最终坑壁的轮廓，台地边缘埋入岩壁，消除绕关漏洞。 */
export function marianaPitReach(x, z, angle, y) {
  const dx = Math.cos(angle),
    dz = Math.sin(angle);
  let reach = Infinity;
  for (let i = 0; i < MARIANA_PIT_SEGMENTS; i++) {
    const a = marianaPitPoint((i * Math.PI * 2) / MARIANA_PIT_SEGMENTS, y),
      b = marianaPitPoint(((i + 1) * Math.PI * 2) / MARIANA_PIT_SEGMENTS, y),
      ex = b[0] - a[0],
      ez = b[1] - a[1],
      denominator = dx * ez - dz * ex;
    if (Math.abs(denominator) < 1e-9) continue;
    const ax = a[0] - x,
      az = a[1] - z,
      t = (ax * ez - az * ex) / denominator,
      u = (ax * dz - az * dx) / denominator;
    if (t > 0 && u >= -1e-8 && u <= 1 + 1e-8) reach = Math.min(reach, t);
  }
  if (!Number.isFinite(reach))
    throw new Error("Mariana gate has no pit boundary");
  return reach;
}

/** 历史侧湾和岩台仍通过同一轮廓查询岩壁，避免附着物沿旧长方形位置悬空。 */
export function marianaPitFace(u, y, back = false, side = 1) {
  const f = marianaPitFrame(y);
  let face = back ? Infinity : side * -Infinity;
  for (let i = 0; i < MARIANA_PIT_SEGMENTS; i++) {
    const a = marianaPitPoint((i * Math.PI * 2) / MARIANA_PIT_SEGMENTS, y),
      b = marianaPitPoint(((i + 1) * Math.PI * 2) / MARIANA_PIT_SEGMENTS, y),
      along = back ? 0 : 1,
      axis = back ? 1 : 0,
      delta = b[along] - a[along];
    if (Math.abs(delta) < 1e-9) continue;
    const t = (u - a[along]) / delta;
    if (t < 0 || t > 1) continue;
    const v = a[axis] + (b[axis] - a[axis]) * t;
    face = back
      ? Math.min(face, v)
      : side > 0
        ? Math.max(face, v)
        : Math.min(face, v);
  }
  return Number.isFinite(face) ? face : back ? f.z - f.back : f.x + side * f.rx;
}

mariana_marine.js.source:
import * as THREE from "three";
import { marianaPitPoint, marianaPitFrame } from "./mariana_pit_profile.js";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import { addSurfaceDetail } from "./ocean_visuals.js";

/** 将软体底栖装饰贴附最终岩壁三角形；不增加食物、伤害或阻挡通道的碰撞体。 */
export function addMarianaMarine({ root, keep, group, floor, time }) {
  const mat = (name, color, emissive = 0) => {
    const m = keep(
      new THREE.MeshStandardMaterial({
        color,
        roughness: 0.86,
        side: THREE.DoubleSide,
        emissive,
        emissiveIntensity: emissive ? 0.35 : 0,
      }),
    );
    m.name = name;
    addSurfaceDetail(m, "coral", 1.7);
    return m;
  };
  const sponge = mat("trench_glass_sponge", 0xc9d4c2),
    anemone = mat("trench_anemone", 0xc17560),
    crust = mat("trench_encrusting_plates", 0x839fa5),
    star = mat("trench_brittle_star", 0xcfae82),
    glow = mat("trench_living_glimmer", 0x6bc6ce, 0x368cab);
  // 动态只在GPU推进，根部位移为零，不逐帧遍历实例。
  const previous = anemone.onBeforeCompile;
  anemone.onBeforeCompile = (s, r) => {
    previous(s, r);
    s.uniforms.marineTime = time;
    s.vertexShader = s.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nuniform float marineTime;",
      )
      .replace(
        "#include <begin_vertex>",
        "#include <begin_vertex>\ntransformed.x+=sin(marineTime*.65+position.y*2.)*pow(max(0.,position.y),2.)*.035;",
      );
  };
  anemone.customProgramCacheKey = () => "mariana_anemone_surface_v1";
  const geometries = [
    keep(spongeGeometry()),
    keep(anemoneGeometry()),
    keep(plateGeometry()),
    keep(starGeometry()),
    keep(new THREE.SphereGeometry(0.16, 8, 6).translate(0, 0.12, 0)),
  ];
  const materials = [sponge, anemone, crust, star, glow];
  const ray = new THREE.Raycaster(),
    up = new THREE.Vector3(0, 1, 0),
    normal = new THREE.Vector3(),
    dummy = new THREE.Object3D();
  const records = [];
  root.updateMatrixWorld(true);
  let seed = 7293;
  const random = () => {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  const walls = [];
  root.traverse((n) => {
    if (n.isMesh && /^trench_(side|back|front)_/.test(n.name)) walls.push(n);
  });
  const buckets = new Map();
  function attach(host, origin, direction, type, scale, section) {
    ray.set(origin, direction);
    ray.far = 5200;
    const hit = ray.intersectObject(host, false)[0];
    if (!hit) return;
    normal.copy(hit.face.normal).transformDirection(host.matrixWorld);
    if (normal.dot(direction) > 0) normal.negate();
    dummy.position.copy(hit.point).addScaledVector(normal, -0.035);
    dummy.quaternion.setFromUnitVectors(up, normal);
    dummy.rotateY(random() * Math.PI * 2);
    dummy.scale.setScalar(scale);
    dummy.updateMatrix();
    const key = `${section}:${type}`;
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(dummy.matrix.clone());
    records.push({
      host: host.name,
      type,
      root: hit.point.toArray(),
      normal: normal.toArray(),
      scale,
      section,
    });
  }
  for (const host of walls) {
    const section = Number(host.name.split("_").at(-1)),
      [start, end] = host.userData.pitSector.angles;
    const amount = section > 12 ? 5 : 10;
    for (let patch = 0; patch < amount; patch++) {
      const angle = start + (0.06 + random() * 0.88) * (end - start),
        y = -section * 180 - 20 - random() * 135;
      for (let item = 0; item < 6; item++) {
        const a = angle + (random() - 0.5) * 0.025,
          yy = y + (random() - 0.5) * 10,
          point = marianaPitPoint(a, yy),
          frame = marianaPitFrame(yy),
          origin = new THREE.Vector3(frame.x, yy, frame.z),
          direction = new THREE.Vector3(
            point[0] - frame.x,
            0,
            point[1] - frame.z,
          ).normalize();
        const type =
          item === 0 ? 0 : item === 1 ? 1 : item === 2 ? 2 : patch % 2 ? 3 : 4;
        attach(
          host,
          origin,
          direction,
          type,
          (type === 4 ? 1.8 : type === 0 ? 3.4 : 2.7) +
            random() * (type === 0 ? 1.8 : 1.4),
          section,
        );
      }
    }
  }
  // 陡坡顶部到下层出口也有附着群落，采样最终地形，避免只装饰两侧而漏掉下降坑面。
  for (let i = 0; i < 120; i++) {
    const z = -90 - random() * 162,
      x = (random() - 0.5) * 350;
    ray.set(new THREE.Vector3(x, 30, z), new THREE.Vector3(0, -1, 0));
    ray.far = 2900;
    const hit = ray.intersectObject(floor, false)[0];
    if (!hit) continue;
    const section = Math.min(15, Math.floor(-hit.point.y / 180));
    const p = hostPoint(floor, hit.face.a),
      q = hostPoint(floor, hit.face.b),
      r = hostPoint(floor, hit.face.c);
    normal.copy(hit.face.normal).transformDirection(floor.matrixWorld);
    if (normal.y < 0) normal.negate();
    for (let j = 0; j < 6; j++) {
      const target = [p, q, r][j % 3],
        point = hit.point.clone().lerp(target, 0.02 + j * 0.009);
      dummy.position.copy(point).addScaledVector(normal, -0.035);
      dummy.quaternion.setFromUnitVectors(up, normal);
      dummy.rotateY(random() * Math.PI * 2);
      dummy.scale.setScalar(0.8 + random() * 1.5);
      dummy.updateMatrix();
      const type = (i + j) % 5,
        key = `${section}:${type}`;
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(dummy.matrix.clone());
      records.push({
        host: floor.name,
        type,
        root: point.toArray(),
        normal: normal.toArray(),
        scale: dummy.scale.x,
        section,
      });
    }
  }
  for (let section = 0; section < 16; section++) {
    const g = group(`trench_marine_${section}`, -section * 180 - 90);
    for (let type = 0; type < 5; type++) {
      const matrices = buckets.get(`${section}:${type}`);
      if (!matrices) continue;
      const mesh = new THREE.InstancedMesh(
        geometries[type],
        materials[type],
        matrices.length,
      );
      mesh.name = `trench_marine_${section}_${materials[type].name}`;
      matrices.forEach((matrix, i) => mesh.setMatrixAt(i, matrix));
      const palette =
        section < 4
          ? [0xced6b6, 0xd39378, 0x8aac97, 0xd2b27e]
          : section < 8
            ? [0xa1c8cc, 0x988ed0, 0x7aa1c1, 0xc39da0]
            : section < 12
              ? [0xd1b7ce, 0x9c92c6, 0x8491ac, 0xc6b8a2]
              : [0xd3d4c3, 0xb29ead, 0x9aafb1, 0xdacdb0];
      const tint = new THREE.Color(type === 4 ? 0xffffff : palette[type]);
      for (let i = 0; i < matrices.length; i++) mesh.setColorAt(i, tint);
      mesh.instanceMatrix.needsUpdate = true;
      mesh.computeBoundingBox();
      mesh.computeBoundingSphere();
      g.add(mesh);
    }
  }
  // 开发验收用轻量元数据：每个附着点可重新射线验证，不将宿主或临时几何留在闭包中。
  root.userData.marineAttachments = records;
  return { count: records.length };
}

function spongeGeometry() {
  return new THREE.LatheGeometry(
    [
      new THREE.Vector2(0.18, 0),
      new THREE.Vector2(0.25, 0.25),
      new THREE.Vector2(0.42, 0.7),
      new THREE.Vector2(0.63, 1.6),
      new THREE.Vector2(0.59, 2.3),
      new THREE.Vector2(0.48, 2.38),
      new THREE.Vector2(0.4, 2.25),
      new THREE.Vector2(0.44, 1.6),
      new THREE.Vector2(0.27, 0.72),
      new THREE.Vector2(0.1, 0.38),
    ],
    20,
  );
}
function merge(parts) {
  const g = mergeGeometries(parts);
  parts.forEach((p) => p.dispose());
  return g;
}
function anemoneGeometry() {
  const parts = [
    new THREE.SphereGeometry(0.42, 12, 8)
      .scale(1, 0.75, 1)
      .translate(0, 0.2, 0),
  ];
  for (let i = 0; i < 16; i++) {
    const a = (i * Math.PI) / 8,
      r = 0.28;
    const points = [
      new THREE.Vector3(Math.cos(a) * r, 0.2, Math.sin(a) * r),
      new THREE.Vector3(Math.cos(a) * 0.55, 0.6, Math.sin(a) * 0.55),
      new THREE.Vector3(
        Math.cos(a) * 0.92,
        0.98 + (i % 3) * 0.1,
        Math.sin(a) * 0.92,
      ),
      new THREE.Vector3(Math.cos(a) * 1.06, 0.73, Math.sin(a) * 1.06),
    ];
    parts.push(
      new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(points),
        8,
        0.045,
        5,
        false,
      ),
    );
  }
  return merge(parts);
}
function plateGeometry() {
  const parts = [];
  for (let i = 0; i < 5; i++) {
    const g = new THREE.SphereGeometry(1, 14, 6),
      p = g.attributes.position;
    for (let k = 0; k < p.count; k++) {
      const x = p.getX(k),
        z = p.getZ(k),
        a = Math.atan2(z, x);
      p.setXYZ(
        k,
        x * (1 + Math.sin(a * 7 + i) * 0.1),
        p.getY(k) * 0.07,
        z * (1 + Math.cos(a * 9) * 0.1),
      );
    }
    g.computeVertexNormals();
    g.scale(1 - i * 0.12, 1, 1 - i * 0.12);
    g.translate(
      Math.sin(i * 2.4) * 0.35,
      0.1 + i * 0.16,
      Math.cos(i * 2.4) * 0.3,
    );
    parts.push(g);
  }
  return merge(parts);
}
function starGeometry() {
  const parts = [
    new THREE.SphereGeometry(0.24, 10, 6)
      .scale(1, 0.38, 1)
      .translate(0, 0.1, 0),
  ];
  for (let i = 0; i < 5; i++) {
    const a = (i * Math.PI * 2) / 5,
      points = [];
    for (let j = 0; j < 6; j++) {
      const r = j * 0.27,
        t = a + Math.sin(j * 0.7) * 0.35;
      points.push(
        new THREE.Vector3(
          Math.cos(t) * r,
          0.1 + Math.sin(j * 0.8) * 0.05,
          Math.sin(t) * r,
        ),
      );
    }
    parts.push(
      new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(points),
        12,
        0.065,
        5,
        false,
      ),
    );
  }
  return merge(parts);
}

function hostPoint(host, index) {
  return new THREE.Vector3()
    .fromBufferAttribute(host.geometry.attributes.position, index)
    .applyMatrix4(host.matrixWorld);
}

ocean_visuals.js.source:
import * as THREE from "three";

/**
 * 为共享材质加入无贴图的微表面纹理；实例复用同一程序，细节不改变实体轮廓。
 * @param {THREE.MeshStandardMaterial} material 目标材质。
 * @param {'stone'|'coral'|'wood'|'metal'} kind 纹理类别。
 * @param {number} scale 物体局部纹理密度。
 * @returns {THREE.MeshStandardMaterial} 原材质。
 */
export function addSurfaceDetail(material, kind = "stone", scale = 1) {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous.call(material, shader, renderer);
    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nvarying vec3 vSurfaceDetail;",
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
      vec4 detailPosition = vec4(position, 1.0);
      #ifdef USE_INSTANCING
        detailPosition = instanceMatrix * detailPosition;
      #endif
      vSurfaceDetail = detailPosition.xyz;`,
      );
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <common>",
      `#include <common>
      varying vec3 vSurfaceDetail;
      float detailHash(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.yzx + 33.33); return fract((p.x + p.y) * p.z); }
      float detailNoise(vec3 p) {
        vec3 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
        return mix(mix(mix(detailHash(i),detailHash(i+vec3(1,0,0)),f.x),mix(detailHash(i+vec3(0,1,0)),detailHash(i+vec3(1,1,0)),f.x),f.y),mix(mix(detailHash(i+vec3(0,0,1)),detailHash(i+vec3(1,0,1)),f.x),mix(detailHash(i+vec3(0,1,1)),detailHash(i+vec3(1,1,1)),f.x),f.y),f.z);
      }`,
    );
    const patterns = {
      stone: `float broad = detailNoise(p * 0.65); float grain = detailNoise(p * 8.0);
        float strata = pow(0.5 + 0.5 * sin(p.y * 7.0 + broad * 8.0), 7.0);
        float pits = smoothstep(0.65, 0.84, grain);
        float relief = broad * 0.07 + grain * 0.028 - strata * 0.024;
        diffuseColor.rgb *= 0.83 + broad * 0.20 + grain * 0.12 - strata * 0.09 - pits * 0.10;
        diffuseColor.rgb += vec3(0.04, 0.039, 0.027) * smoothstep(0.53, 0.81, broad);`,
      coral: `float grain = detailNoise(p * 12.0); float pores = pow(0.5 + 0.5 * sin(p.x * 21.0 + sin(p.z * 18.0)) * sin(p.y * 25.0 + p.z * 7.0), 5.0);
        float relief = grain * 0.05 - pores * 0.04;
        diffuseColor.rgb *= 0.88 + grain * 0.2 - pores * 0.30;`,
      wood: `float grain = detailNoise(vec3(p.x * 7.0, p.y * 3.0, p.z * 0.6));
        float plank = abs(fract(p.x * 2.8) - 0.5);
        float joint = smoothstep(0.46, 0.497, plank);
        float relief = grain * 0.014 - joint * 0.016;
        diffuseColor.rgb *= 0.79 + grain * 0.36 - joint * 0.36;`,
      metal: `float grain = detailNoise(p * 60.0);
        float relief = grain * 0.0005;
        diffuseColor.rgb *= 0.94 + grain * 0.08;`,
    };
    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <color_fragment>",
        `#include <color_fragment>
        vec3 p = vSurfaceDetail * ${Number(scale).toFixed(3)};
        ${patterns[kind] || patterns.stone}
      `,
      )
      .replace(
        "#include <normal_fragment_maps>",
        `#include <normal_fragment_maps>
        vec3 detailDx = dFdx(-vViewPosition), detailDy = dFdy(-vViewPosition);
        vec3 detailR1 = cross(detailDy, normal), detailR2 = cross(normal, detailDx);
        float detailDet = dot(detailDx, detailR1);
        vec3 detailGradient = sign(detailDet) * (dFdx(relief) * detailR1 + dFdy(relief) * detailR2);
        normal = normalize(abs(detailDet) * normal - detailGradient * 0.24 + normal * 0.000001);
      `,
      );
  };
  material.customProgramCacheKey = () => `abyssal_surface_${kind}_${scale}_v6`;
  return material;
}

/** 创建底部固定、逐渐弯曲变细的带状叶片；tuft=true 时合并五片海草。 */
export function ribbonGeometry(tuft = false) {
  const positions = [],
    indices = [],
    uvs = [];
  const blades = tuft ? 3 : 1,
    rows = 10,
    columns = 3;
  for (let blade = 0; blade < blades; blade++) {
    const base = positions.length / 3,
      angle = blade * 2.399,
      height = tuft ? 0.72 + blade * 0.07 : 1;
    for (let row = 0; row <= rows; row++) {
      const t = row / rows;
      const width =
        (tuft ? 0.085 : 0.2) * Math.pow(Math.sin(Math.PI * t), 0.62) + 0.002;
      for (let column = 0; column < columns; column++) {
        const side = column - 1;
        const x = side * width + Math.sin(t * 2.2) * t * (tuft ? 0.58 : 0.38);
        const z =
          Math.sin(t * 5.2) * t * 0.11 +
          Math.abs(side) * Math.sin(t * Math.PI) * 0.028;
        positions.push(
          x * Math.cos(angle) - z * Math.sin(angle),
          (t - 0.2 * t * t) * height,
          x * Math.sin(angle) + z * Math.cos(angle),
        );
        uvs.push(column / 2, t);
        if (row < rows && column < columns - 1) {
          const a = base + row * columns + column;
          indices.push(
            a,
            a + columns,
            a + 1,
            a + 1,
            a + columns,
            a + columns + 1,
          );
        }
      }
    }
  }
  return geometryFrom(positions, indices, uvs);
}

/** 圆润枝状珊瑚的单枝，多个实例仍沿原来固定的分叉位置组合。 */
export function coralBranchGeometry() {
  const positions = [],
    indices = [],
    rows = 8,
    sides = 7;
  for (let row = 0; row <= rows; row++) {
    const t = row / rows;
    const radius =
      (0.15 - t * 0.032) *
      Math.pow(Math.max(0.004, Math.sin(Math.PI * t)), 0.28);
    for (let side = 0; side < sides; side++) {
      const a = (side / sides) * Math.PI * 2;
      const r = radius * (1 + Math.sin(a * 3 + t * 14) * 0.09);
      positions.push(
        Math.cos(a) * r + Math.sin(t * 4) * 0.07,
        t - 0.5,
        Math.sin(a) * r + Math.sin(t * 7) * 0.035,
      );
      if (row < rows) {
        const p = row * sides + side,
          n = row * sides + ((side + 1) % sides);
        indices.push(p, p + sides, n, n, p + sides, n + sides);
      }
    }
  }
  return geometryFrom(positions, indices);
}

/** 海扇以分叉细带和横向连接构成真实孔隙，不使用整张透明扇面。 */
export function seaFanGeometry() {
  const positions = [],
    indices = [];
  const segment = (a, b, radius) => {
    const d = new THREE.Vector3().subVectors(b, a).normalize();
    const p = new THREE.Vector3(-d.y, d.x, 0).multiplyScalar(radius);
    const base = positions.length / 3;
    for (const q of [
      a.clone().add(p),
      a.clone().sub(p),
      b.clone().addScaledVector(p, 0.68),
      b.clone().addScaledVector(p, -0.68),
    ])
      positions.push(q.x, q.y, q.z);
    indices.push(base, base + 1, base + 2, base + 1, base + 3, base + 2);
  };
  segment(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0.3, 0), 0.045);
  const ribs = [];
  for (let rib = 0; rib < 17; rib++) {
    const theta = -1.32 + (rib / 16) * 2.64 + Math.sin(rib * 7.3) * 0.017,
      nodes = [new THREE.Vector3(0, 0.2, 0)];
    for (let step = 1; step <= 9; step++) {
      const t = step / 9;
      const point = new THREE.Vector3(
        Math.sin(theta) * t * 0.9 +
          Math.sin(step * 1.8 + rib * 2.3) * t * 0.023,
        0.2 + Math.cos(theta * 0.78) * t * (1.02 + Math.sin(rib * 3.1) * 0.055),
        Math.sin(t * 5 + theta) * t * 0.065,
      );
      segment(nodes.at(-1), point, 0.018 * (1 - t * 0.55));
      if (rib && step > 2 && (rib + step) % 3 !== 0)
        segment(point, ribs[rib - 1][step - (step % 2)], 0.007);
      nodes.push(point);
    }
    ribs.push(nodes);
  }
  return geometryFrom(positions, indices);
}

/** 团簇脑珊瑚保持圆润轮廓，沟壑来自共享程序材质而非尖锐低面球。 */
export function moundCoralGeometry() {
  const geometry = new THREE.SphereGeometry(1, 16, 10);
  const p = geometry.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i),
      y = p.getY(i),
      z = p.getZ(i);
    const r = 1 + 0.1 * Math.sin(x * 7 + y * 3) * Math.sin(z * 8 - y * 4);
    p.setXYZ(i, x * r, y * r, z * r);
  }
  geometry.computeVertexNormals();
  return geometry;
}

/** 按相同顶点位置平均法线，仅修正岩石光照，不移动任何碰撞包络顶点。 */
export function smoothCoincidentNormals(geometry) {
  const p = geometry.attributes.position,
    n = geometry.attributes.normal,
    groups = new Map();
  for (let i = 0; i < p.count; i++) {
    const key = `${p.getX(i).toFixed(5)},${p.getY(i).toFixed(5)},${p.getZ(i).toFixed(5)}`;
    if (!groups.has(key))
      groups.set(key, { normal: new THREE.Vector3(), indices: [] });
    const group = groups.get(key);
    group.indices.push(i);
    group.normal.add(new THREE.Vector3().fromBufferAttribute(n, i));
  }
  for (const group of groups.values()) {
    group.normal.normalize();
    for (const i of group.indices)
      n.setXYZ(i, group.normal.x, group.normal.y, group.normal.z);
  }
  return geometry;
}

function geometryFrom(positions, indices, uvs) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  if (uvs)
    geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

/** 将大片植被按空间块拆为共享几何的实例批次，使视锥剔除只提交附近叶片。 */
export function clusterInstances(source, cellSize = 90) {
  const groups = new Map(),
    matrix = new THREE.Matrix4(),
    point = new THREE.Vector3(),
    color = new THREE.Color();
  for (let i = 0; i < source.count; i++) {
    source.getMatrixAt(i, matrix);
    point.setFromMatrixPosition(matrix);
    const key = `${Math.floor(point.x / cellSize)}_${Math.floor(point.z / cellSize)}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(i);
  }
  const root = new THREE.Group();
  root.name = `${source.name || "vegetation"}_clusters`;
  for (const indices of groups.values()) {
    const batch = new THREE.InstancedMesh(
      source.geometry,
      source.material,
      indices.length,
    );
    for (let i = 0; i < indices.length; i++) {
      source.getMatrixAt(indices[i], matrix);
      batch.setMatrixAt(i, matrix);
      if (source.instanceColor) {
        source.getColorAt(indices[i], color);
        batch.setColorAt(i, color);
      }
    }
    batch.computeBoundingSphere();
    batch.boundingSphere.radius += 3;
    root.add(batch);
  }
  source.dispose();
  return root;
}

/** 叶片根部自然变暗、叶缘透亮，并用低对比细脉帮助近景阅读。 */
export function addLeafDetail(material) {
  const previous = material.onBeforeCompile,
    previousKey = material.customProgramCacheKey();
  material.onBeforeCompile = (shader, renderer) => {
    previous.call(material, shader, renderer);
    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        "#include <common>\nvarying vec2 vLeafDetail;",
      )
      .replace(
        "#include <begin_vertex>",
        "#include <begin_vertex>\nvLeafDetail = uv;",
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        "#include <common>\nvarying vec2 vLeafDetail;",
      )
      .replace(
        "#include <color_fragment>",
        `#include <color_fragment>
      float midrib = exp(-abs(vLeafDetail.x - 0.5) * 65.0);
      float veins = sin(vLeafDetail.y * 95.0 + abs(vLeafDetail.x - 0.5) * 19.0) * 0.025;
      diffuseColor.rgb *= 0.64 + vLeafDetail.y * 0.42 + midrib * 0.18 + veins;
    `,
      );
  };
  material.customProgramCacheKey = () => `${previousKey}_leaf_v6`;
  return material;
}

mariana_passages.js.source:
import * as THREE from "three";

/** 岩台上的天然拱廊形成短绕路；弧管与接触胶囊使用同一中心线。 */
export function addMarianaPassage(parent, keep, material, center, id) {
  const [x, y, z] = center;
  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(x - 46, y + 4, z),
    new THREE.Vector3(x - 45, y + 33, z - 3),
    new THREE.Vector3(x - 29, y + 64, z),
    new THREE.Vector3(x, y + 77, z + 2),
    new THREE.Vector3(x + 30, y + 62, z),
    new THREE.Vector3(x + 45, y + 31, z - 3),
    new THREE.Vector3(x + 46, y + 4, z),
  ]);
  const geometry = keep(new THREE.TubeGeometry(curve, 56, 5.5, 12, false));
  // 风化的岩拱截面沿中心线变化，所有削蚀都留在既有胶囊实体内。
  const vertices = geometry.attributes.position;
  for (let i = 0; i < vertices.count; i++) {
    const t = Math.floor(i / 13) / 56;
    const centerline = curve.getPointAt(Math.min(1, t));
    const px = vertices.getX(i),
      py = vertices.getY(i),
      pz = vertices.getZ(i);
    const erosion =
      0.85 +
      0.13 * Math.sin(px * 0.39 + py * 0.27) * Math.sin(pz * 0.53 - py * 0.18);
    vertices.setXYZ(
      i,
      centerline.x + (px - centerline.x) * erosion,
      centerline.y + (py - centerline.y) * erosion,
      centerline.z + (pz - centerline.z) * erosion,
    );
  }
  geometry.computeVertexNormals();
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = id;
  parent.add(mesh);
  const points = curve.getSpacedPoints(56);
  return points.slice(1).map((p, i) => ({
    type: "capsule",
    id: `${id}_${i}`,
    a: points[i],
    b: p,
    radius: 5.6,
  }));
}

mariana_cliffs.js.source:
import * as THREE from "three";
import {
  MARIANA_PIT_SEGMENTS,
  marianaPitPoint,
  marianaPitFrame,
  marianaPitRim,
  marianaPitFace,
} from "./mariana_pit_profile.js";

/** 闭合岩体围出弯曲深坑，前壁同样参与渲染与碰撞；分块仅用于深度裁切。 */
export function createMarianaCliff(
  parent,
  keep,
  { top, bottom, side = 1, back = false, front = false, material, id },
) {
  const sector = front
      ? [24, 48]
      : back
        ? [96, 120]
        : side < 0
          ? [48, 96]
          : [120, 168],
    nu = sector[1] - sector[0],
    nv = 12,
    nr = top === 0 ? 6 : 1,
    positions = [],
    colors = [],
    indices = [],
    colliders = [],
    color = new THREE.Color(),
    dark = new THREE.Color(),
    light = new THREE.Color();
  const at = (r, v, u) => (r * (nv + 1) + v) * (nu + 1) + u;
  for (let r = 0; r <= nr; r++)
    for (let v = 0; v <= nv; v++)
      for (let u = 0; u <= nu; u++) {
        const angle =
            (((sector[0] + u) % MARIANA_PIT_SEGMENTS) * Math.PI * 2) /
            MARIANA_PIT_SEGMENTS,
          t = r / nr,
          rim = Math.min(top, marianaPitRim(angle)),
          outerTop = top === 0 ? -38 - Math.max(0, -Math.sin(angle)) * 14 : top,
          cap =
            THREE.MathUtils.lerp(rim, outerTop, t) +
            (top === 0 ? Math.sin(t * Math.PI) * Math.cos(angle * 7) * 12 : 0),
          y = THREE.MathUtils.lerp(cap, bottom, v / nv),
          inner = marianaPitPoint(angle, y),
          frame = marianaPitFrame(y),
          x = THREE.MathUtils.lerp(
            inner[0],
            frame.x + Math.cos(angle) * 700,
            t,
          ),
          z = THREE.MathUtils.lerp(
            inner[1],
            frame.z + Math.sin(angle) * 900,
            t,
          );
        positions.push(x, y, z);
        const palette = marianaLayerPalette(y);
        dark.set(palette[0]);
        light.set(palette[1]);
        color
          .copy(dark)
          .lerp(
            light,
            0.24 +
              0.45 *
                (0.5 +
                  0.5 *
                    Math.sin(y * 0.16 + angle * 13 + Math.sin(y * 0.025) * 2)),
          );
        color.toArray(colors, colors.length);
      }
  function quad(a, b, c, d) {
    indices.push(a, b, c, b, d, c);
  }
  for (let v = 0; v < nv; v++)
    for (let u = 0; u < nu; u++) {
      quad(at(0, v, u), at(0, v + 1, u), at(0, v, u + 1), at(0, v + 1, u + 1));
      quad(
        at(nr, v, u),
        at(nr, v, u + 1),
        at(nr, v + 1, u),
        at(nr, v + 1, u + 1),
      );
    }
  for (let r = 0; r < nr; r++)
    for (let u = 0; u < nu; u++) {
      quad(at(r, 0, u), at(r, 0, u + 1), at(r + 1, 0, u), at(r + 1, 0, u + 1));
      quad(
        at(r, nv, u),
        at(r + 1, nv, u),
        at(r, nv, u + 1),
        at(r + 1, nv, u + 1),
      );
    }
  for (let r = 0; r < nr; r++)
    for (let v = 0; v < nv; v++) {
      quad(at(r, v, 0), at(r + 1, v, 0), at(r, v + 1, 0), at(r + 1, v + 1, 0));
      quad(
        at(r, v, nu),
        at(r, v + 1, nu),
        at(r + 1, v, nu),
        at(r + 1, v + 1, nu),
      );
    }
  // 分层扇形实体填满岩壁外侧；坑内仅保留每个细单元的保守接触余量。
  for (let r = 0; r < nr; r++)
    for (let v = 0; v < nv; v++)
      for (let u = 0; u < nu; u++) {
        const lo = [Infinity, Infinity, Infinity],
          hi = [-Infinity, -Infinity, -Infinity];
        for (const rr of [r, r + 1])
          for (const vv of [v, v + 1])
            for (const uu of [u, u + 1])
              for (let k = 0; k < 3; k++) {
                const n = positions[at(rr, vv, uu) * 3 + k];
                lo[k] = Math.min(lo[k], n);
                hi[k] = Math.max(hi[k], n);
              }
        colliders.push({
          type: "box",
          id: `${id}_${r}_${v}_${u}`,
          x: (lo[0] + hi[0]) / 2,
          y: (lo[1] + hi[1]) / 2,
          z: (lo[2] + hi[2]) / 2,
          halfSize: new THREE.Vector3(...hi.map((n, k) => (n - lo[k]) / 2)),
        });
      }
  const geometry = keep(new THREE.BufferGeometry());
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  // 岩壁沿纵深保持同一曲面法线，封口面不会在每个剔除分段上制造黑色横缝。
  const normal = geometry.attributes.normal,
    tangent = new THREE.Vector3(),
    vertical = new THREE.Vector3(),
    wallNormal = new THREE.Vector3();
  for (let v = 0; v <= nv; v++)
    for (let u = 0; u <= nu; u++) {
      const i = at(0, v, u),
        y = positions[i * 3 + 1],
        angle = ((sector[0] + u) * Math.PI * 2) / MARIANA_PIT_SEGMENTS,
        a = marianaPitPoint(angle - 0.0001, y),
        b = marianaPitPoint(angle + 0.0001, y),
        low = marianaPitPoint(angle, y - 0.01),
        high = marianaPitPoint(angle, y + 0.01);
      tangent.set(b[0] - a[0], 0, b[1] - a[1]);
      vertical.set(high[0] - low[0], 0.02, high[1] - low[1]);
      wallNormal.copy(tangent).cross(vertical).normalize();
      normal.setXYZ(i, wallNormal.x, wallNormal.y, wallNormal.z);
    }
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = id;
  mesh.userData.pitSector = {
    angles: sector.map((i) => (i * Math.PI * 2) / MARIANA_PIT_SEGMENTS),
    top,
    bottom,
  };
  parent.add(mesh);
  return colliders;
}

export const marianaCliffFace = marianaPitFace;

/** 各层使用连续过渡的沉积岩色，不把深水全部染成同一种灰蓝。 */
export function marianaLayerPalette(y) {
  return y > -650
    ? [0x485952, 0xb6b09a]
    : y > -1000
      ? [0x334c63, 0x91b2bc]
      : y > -1375
        ? [0x4c435d, 0xaa9cab]
        : y > -2150
          ? [0x353949, 0x7a91a7]
          : [0x54616b, 0xb9c0b6];
}

bermuda_geometry.js.source:
import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import { addSurfaceDetail } from "./ocean_visuals.js";

/** 地图几何按材质合批；临时几何合并后释放，碰撞与装饰拥有明确边界。 */
export function createBermudaBuilder(root, keep, origin = new THREE.Vector3()) {
  const buckets = new Map(),
    colliders = [];
  let sequence = 0;
  function add(geometry, material, position = [0, 0, 0], rotation = [0, 0, 0]) {
    const matrix = new THREE.Matrix4().compose(
      new THREE.Vector3(...position),
      new THREE.Quaternion().setFromEuler(new THREE.Euler(...rotation)),
      new THREE.Vector3(1, 1, 1),
    );
    geometry.applyMatrix4(matrix);
    if (!geometry.attributes.uv)
      geometry.setAttribute(
        "uv",
        new THREE.BufferAttribute(
          new Float32Array(geometry.attributes.position.count * 2),
          2,
        ),
      );
    if (!buckets.has(material)) buckets.set(material, []);
    buckets.get(material).push(geometry);
  }
  function box(material, center, size, solid = false, rotation = 0) {
    const angles = Array.isArray(rotation) ? rotation : [0, rotation, 0];
    add(new THREE.BoxGeometry(...size), material, center, angles);
    const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(...angles));
    if (solid)
      colliders.push({
        type: "box",
        id: `${root.name}_${sequence++}`,
        x: center[0] + origin.x,
        y: center[1] + origin.y,
        z: center[2] + origin.z,
        halfSize: new THREE.Vector3(...size).multiplyScalar(0.5),
        rotation: { x: q.x, y: q.y, z: q.z, w: q.w },
      });
  }
  function beam(material, a, b, radius = 0.15, sides = 8) {
    const from = new THREE.Vector3(...a),
      to = new THREE.Vector3(...b),
      direction = to.clone().sub(from);
    const geometry = new THREE.CylinderGeometry(
      radius,
      radius,
      direction.length(),
      sides,
    );
    geometry.applyQuaternion(
      new THREE.Quaternion().setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize(),
      ),
    );
    add(geometry, material, from.add(to).multiplyScalar(0.5).toArray());
  }
  function finish() {
    for (const [material, geometries] of buckets) {
      const geometry = keep(mergeGeometries(geometries));
      for (const temporary of geometries) temporary.dispose();
      geometry.computeBoundingSphere();
      const mesh = new THREE.Mesh(geometry, material);
      mesh.name = `${root.name}_${material.name}`;
      root.add(mesh);
    }
    buckets.clear();
    return colliders;
  }
  return { add, box, beam, finish, colliders };
}

/** 腐蚀钢、木材、铜和生物冷光，细节由现有表面着色器生成。 */
export function bermudaMaterials(keep) {
  function mat(name, color, roughness = 0.8, metalness = 0) {
    const material = keep(
      new THREE.MeshStandardMaterial({ color, roughness, metalness }),
    );
    material.name = name;
    return material;
  }
  const palette = {
    steel: mat("corroded_steel", "#526169", 0.78, 0.3),
    rust: mat("oxide", "#8a4d31", 0.9, 0.15),
    pale: mat("aged_enamel", "#b2b9af", 0.75),
    wood: mat("waterlogged_wood", "#544537", 0.94),
    brass: mat("verdigris_brass", "#66847a", 0.56, 0.48),
    dark: mat("charcoal", "#141f28", 0.84),
    red: mat("funnel_ochre", "#a77349", 0.85),
    glass: mat("broken_glass", "#263f49", 0.3, 0.25),
    coral: mat("red_coral", "#ad4842", 0.78),
    pearl: mat("bioluminescence", "#77bdb1", 0.5),
  };
  for (const key of ["steel", "rust", "brass", "pale"])
    addSurfaceDetail(palette[key], "metal", key === "rust" ? 0.9 : 0.35);
  addSurfaceDetail(palette.wood, "wood", 0.75);
  palette.pearl.emissive.set("#5ee9d0");
  palette.pearl.emissiveIntensity = 1.4;
  return palette;
}

/** 分段截面的船壳，保留上方开口和指定舷侧破口，法线与真实薄壁一致。 */
export function hullStripGeometry(
  length,
  width,
  height,
  { side = 1, broken = false } = {},
) {
  const p = [],
    indices = [],
    steps = 64;
  for (let row = 0; row <= steps; row++) {
    const z = (row / steps - 0.5) * length;
    const taper = Math.min(
      1,
      Math.max(0.03, (length / 2 - Math.abs(z)) / (length * 0.12)),
    );
    for (let level = 0; level < 5; level++) {
      const y = (height * level) / 4;
      const flare = 0.55 + Math.sin(((level / 4) * Math.PI) / 2) * 0.45;
      p.push(((side * width) / 2) * taper * flare, y, z);
    }
  }
  for (let row = 0; row < steps; row++) {
    const z = ((row + 0.5) / steps - 0.5) * length;
    for (let level = 0; level < 4; level++) {
      if (broken && side === 1 && z > 30 && z < 68 && level >= 1 && level <= 2)
        continue;
      const a = row * 5 + level,
        b = a + 5;
      const faces =
        side === 1
          ? [a, b, a + 1, b, b + 1, a + 1]
          : [a, a + 1, b, b, a + 1, b + 1];
      indices.push(...faces);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(p, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

bermuda_reef.js.source:
import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";

/** 合并有主干、侧枝和浅色生长尖端的鹿角珊瑚；底部位于原点，供共享实例使用。 */
export function bermudaCoralColonyGeometry() {
  const pieces = [];
  const branch = (points, radius) => {
    const curve = new THREE.CatmullRomCurve3(
      points.map((p) => new THREE.Vector3(...p)),
    );
    const g = new THREE.TubeGeometry(curve, 9, radius, 6, false);
    const positions = g.attributes.position;
    const colors = [];
    for (let i = 0; i < positions.count; i++) {
      const t = Math.floor(i / 7) / 9;
      const center = curve.getPointAt(t);
      const taper = 1 - t * 0.7;
      positions.setXYZ(
        i,
        center.x + (positions.getX(i) - center.x) * taper,
        center.y + (positions.getY(i) - center.y) * taper,
        center.z + (positions.getZ(i) - center.z) * taper,
      );
      const c = new THREE.Color().lerpColors(
        new THREE.Color("#a4654e"),
        new THREE.Color("#ead9b0"),
        Math.pow(t, 6) * 0.7,
      );
      colors.push(c.r, c.g, c.b);
    }
    g.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
    g.computeVertexNormals();
    pieces.push(g);
  };
  branch(
    [
      [0, -0.08, 0],
      [0.015, 0.3, 0],
      [-0.04, 0.65, 0.02],
      [0, 1.08, 0.03],
    ],
    0.065,
  );
  for (let i = 0; i < 7; i++) {
    const a = i * 2.399,
      y = 0.12 + i * 0.075,
      r = 0.36 + (i % 3) * 0.075;
    const x = Math.cos(a) * r,
      z = Math.sin(a) * r;
    branch(
      [
        [0, y, 0],
        [x * 0.48, y + 0.14, z * 0.48],
        [x, y + 0.35, z],
        [x * 1.06, y + 0.7, z * 1.1],
      ],
      0.038,
    );
    branch(
      [
        [x * 0.65, y + 0.23, z * 0.65],
        [x * 0.95, y + 0.3, z * 0.55],
        [x * 1.3, y + 0.53, z * 0.45],
      ],
      0.024,
    );
  }
  const geometry = mergeGeometries(pieces);
  pieces.forEach((g) => g.dispose());
  geometry.computeBoundingSphere();
  return geometry;
}

